        <div class="hero-art"><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="art-card art-a"><el-icon><DocumentChecked /></el-icon><span>文书解析</span></div><div class="art-card art-b"><el-icon><Cpu /></el-icon><span>领域模型</span></div><div class="art-card art-c"><el-icon><Share /></el-icon><span>流程编排</span></div><div class="art-line line-one"></div><div class="art-line line-two"></div></div>
      </section>
      <section class="metrics"><div><el-icon><Files /></el-icon><span>可用模板</span><strong>{{ agentTemplates.length + myTemplates.length }}</strong><small>个</small></div><div><el-icon><Grid /></el-icon><span>业务场景</span><strong>6</strong><small>类</small></div><div><el-icon><User /></el-icon><span>我的模板</span><strong>{{ myTemplates.length }}</strong><small>个</small></div><div><el-icon><CircleCheck /></el-icon><span>已发布流程</span><strong>8</strong><small>条</small></div></section>
      <section class="library">
        <div class="section-title"><div><span class="section-kicker">EXPLORE TEMPLATES</span><h2>探索模板</h2><p>选好模板后即可进入智能体编排页面</p></div><button class="create" @click="createTemplate"><el-icon><Plus /></el-icon> 新建空白模板</button></div>
        <div class="toolbar"><div class="cats"><button v-for="cat in agentCategories" :key="cat" :class="{ active: activeCat === cat }" @click="activeCat = cat">{{ cat }}<small v-if="cat === '我的模板'">{{ myTemplates.length }}</small></button></div><label class="search"><el-icon><Search /></el-icon><input v-model="keyword" placeholder="搜索模板名称、场景或描述" /><button v-if="keyword" @click="keyword = ''" aria-label="清空搜索"><el-icon><Close /></el-icon></button></label></div>
