        <div v-if="shown.length" class="grid"><button v-for="item in shown" :key="item.id" class="card" @click="open(item)"><div class="card-top"><span class="card-icon" :class="item.tone"><el-icon><component :is="icons[item.icon] || Grid" /></el-icon></span><div class="card-heading"><h3>{{ item.name }}</h3><div><span class="kind"><el-icon><Share v-if="item.kind === '工作流'" /><ChatDotRound v-else /></el-icon>{{ item.kind }}</span><span v-if="item.mine" class="mine-tag">我的模板</span><span v-else-if="item.featured" class="featured">热门</span></div></div><el-icon class="card-arrow"><ArrowRight /></el-icon></div><p>{{ item.brief }}</p><div class="card-footer"><span><el-icon><Connection /></el-icon>{{ item.nodes }} 个节点</span><span><el-icon><User /></el-icon>{{ item.owner }}</span><span v-if="!item.mine"><el-icon><View /></el-icon>{{ item.uses }}</span><b>使用模板 <el-icon><ArrowRight /></el-icon></b></div></button></div>
