</template>
<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import * as icons from '@element-plus/icons-vue'
import { Operation, ArrowLeft, ArrowRight, CircleCheck, Connection, DataAnalysis, DocumentChecked, Cpu, Share, Files, Grid, User, Plus, Search, Close, ChatDotRound, View } from '@element-plus/icons-vue'
import { agentTemplates, agentCategories } from '@/data/agentTemplates'
const router = useRouter()
const activeCat = ref('全部模板')
const keyword = ref('')
const myTemplates = ref(readMine())
function readMine() { try { return JSON.parse(localStorage.getItem('agent-my-templates') || '[]') } catch { return [] } }
const shown = computed(() => {
  const word = keyword.value.trim().toLocaleLowerCase()
  const source = activeCat.value === '我的模板' ? myTemplates.value : [...myTemplates.value, ...agentTemplates]
  return source.filter(item => (activeCat.value === '全部模板' || activeCat.value === '我的模板' || item.category === activeCat.value) && (!word || `${item.name} ${item.brief} ${item.category} ${item.kind}`.toLocaleLowerCase().includes(word)))
})
function open(item) { router.push({ name: 'agent-studio', query: { tpl: item.id } }) }
function createTemplate() {
  const item = { id: `mine-${Date.now()}`, name: '未命名智能体', category: '我的模板', kind: '工作流', icon: 'Cpu', tone: 'blue', brief: '从空白画布开始，组合模型、知识库与工具节点，创建专属业务流程。', nodes: 2, owner: '我创建的', mine: true }
  myTemplates.value.unshift(item)
  localStorage.setItem('agent-my-templates', JSON.stringify(myTemplates.value))
  open(item)
}
</script>
